    constructor(C _c) { c = _c; }
    function run(address _requester, bytes32 _digest, uint256 _utxoSize, bytes memory _redeemerOutputScript, uint256 _requestedFee, bytes memory _outpoint) public payable {
        require(true);
        bool obs = c.logRedemptionRequested(_requester, _digest, _utxoSize, _redeemerOutputScript, _requestedFee, _outpoint);
        assert(obs == false || c.approvedToLog(address(this)) == true);
    }
    receive() external payable {}
}
